package com.library.book; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import java.util.*; public interface BookRepository extends JpaRepository<Book,Long>{ List<Book> findByTitleContainingIgnoreCaseOrAuthorContainingIgnoreCase(String t,String a); @Query("select b from Book b where b.onlineAvailable=true and lower(b.title) like lower(concat('%',:q,'%'))") List<Book> searchOnline(String q); }
